INSERT INTO ReadingPassages (PassageID, BankID, Title, Content, CreatedAt) VALUES
  (20001, 20003, 'メモ（会社で）', '田中さん

きょうは 3時から 会議が あります。会議の 前に、2かいの コピーきで しりょうを 10まい コピーして ください。わたしは 2時半ごろ 会社に もどります。

山田', NOW() - INTERVAL 138240 MINUTE),
  (20002, 20003, 'わたしの 一日', 'わたしは グエンです。ベトナムの ハノイから 来ました。いま、東京の 日本語学校で べんきょうして います。

まいあさ 7時に おきて、電車で 学校へ 行きます。学校は 9時から 1時までです。ごごは スーパーで アルバイトを します。しゅうまつは ともだちと こうえんで サッカーを します。', NOW() - INTERVAL 138240 MINUTE),
  (20003, 20006, 'メール：パーティーの 場所', 'リンさん

来週の 金曜日の パーティーの ことですが、場所が かわりました。駅前の レストランは 予約が いっぱいだったので、大学の 近くの 「さくら」という 店に しました。時間は 同じで、7時からです。

「さくら」は 駅から 少し 遠いので、6時半に 駅の 北口で 待ち合わせを しませんか。

木村', NOW() - INTERVAL 138240 MINUTE),
  (20004, 20006, '図書館からの お知らせ', '【図書館からの お知らせ】

・本は 2週間 借りる ことが できます。
・一人 10さつまで 借りられます。
・借りた 本を 返すのが おくれた 人は、返した 日から 1週間、本を 借りる ことが できません。
・雑誌は 図書館の 中で 読んで ください。借りる ことは できません。', NOW() - INTERVAL 138240 MINUTE),
  (20005, 20009, '歩きスマホ', '最近、駅や 電車の 中で スマートフォンを 見ながら 歩く 人が 増えている。画面に 集中して いると、周りの 様子に 気が つかず、人に ぶつかったり、階段で 転んだり する ことが ある。

ある 鉄道会社の 調査では、駅で 起きた けがの うち、約 3割が 歩きスマホに 関係して いたそうだ。便利な 道具だからこそ、使う 場所と 時間を 考える ことが 大切だ。', NOW() - INTERVAL 138240 MINUTE),
  (20006, 20009, '朝の ジョギング', '私は 毎朝、会社へ 行く 前に 30分 ジョギングを して いる。始めた ころは 早く 起きるのが つらくて、何度も やめようと 思った。

しかし、1か月 ほど 続けると、体が 軽く なり、仕事中も 眠く ならなく なった。今では、走らない 日の ほうが 調子が 悪いくらいだ。何かを 習慣に するには、最初の 1か月を がんばる ことが 大切だと 思う。', NOW() - INTERVAL 138240 MINUTE);
INSERT INTO Questions (QuestionID, BankID, Content, QuestionType, DifficultyLevel, IsAIGenerated, Explanation, CreatedAt, IsDeleted, Skill, PassageID) VALUES
  (20001, 20001, '「わたしは まいあさ ７じに ＿＿＿。」', 'MULTIPLE_CHOICE', 1, 0, 'おきます (起きます) = thức dậy. Buổi sáng lúc 7 giờ thì hợp nghĩa nhất. ねます là đi ngủ.', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20002, 20001, 'つぎの ことばの よみかたは どれですか。『山』', 'MULTIPLE_CHOICE', 1, 0, '山 đọc là やま (núi). かわ là 川 (sông), き là 木 (cây), た là 田 (ruộng).', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20003, 20001, 'つぎの ことばの よみかたは どれですか。『水』', 'MULTIPLE_CHOICE', 1, 0, '水 = みず (nước). ひ là 火, き là 木, つち là 土 — bốn chữ này hay đi cùng nhau trong tên các ngày trong tuần.', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20004, 20001, '「きのう デパートで くつを ＿＿＿。」', 'MULTIPLE_CHOICE', 2, 0, 'Ở cửa hàng bách hoá thì hành động tự nhiên là かいました (đã mua). うりました là đã bán — người mua không bán giày ở đó.', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20005, 20001, '「きょうは げつようびです。あしたは ＿＿＿です。」', 'MULTIPLE_CHOICE', 1, 0, 'Thứ tự: げつ (thứ Hai) → か (thứ Ba) → すい (thứ Tư) → もく → きん → ど → にち.', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20006, 20001, '「えきの まえに ＿＿＿が あります。そこで こどもが あそんで います。」', 'MULTIPLE_CHOICE', 2, 0, 'Trẻ con chơi đùa → こうえん (công viên). Ngân hàng, bệnh viện, thư viện đều không phải chỗ chơi.', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20007, 20001, 'つぎの ことばの よみかたは どれですか。『電車』', 'MULTIPLE_CHOICE', 2, 0, '電車 = でんしゃ (tàu điện). でんき là 電気 (điện), じてんしゃ là 自転車 (xe đạp), でんわ là 電話 (điện thoại).', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20008, 20001, '「この へやは ＿＿＿です。なにも きこえません。」', 'MULTIPLE_CHOICE', 2, 0, '"Không nghe thấy gì" → しずか (yên tĩnh). にぎやか là náo nhiệt, trái nghĩa hoàn toàn.', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20009, 20001, 'つぎの ことばの よみかたは どれですか。『先月』', 'MULTIPLE_CHOICE', 3, 0, '先月 = せんげつ (tháng trước). Trong từ ghép Hán, 月 thường đọc げつ hoặc がつ: 今月 こんげつ, 一月 いちがつ.', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20010, 20001, '「あついですね。まどを ＿＿＿ください。」', 'MULTIPLE_CHOICE', 2, 0, 'Trời nóng thì mở cửa sổ → あけて. しめて là đóng. けして / つけて dùng cho đèn, điều hoà, không dùng cho cửa sổ.', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20011, 20001, '「この かばんは かるくないです。」と だいたい おなじ いみの ぶんは どれですか。', 'MULTIPLE_CHOICE', 3, 0, 'かるくない (không nhẹ) ≈ おもい (nặng). Dạng bài "diễn đạt lại" hỏi ý nghĩa, không hỏi từ giống hệt.', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20012, 20001, 'つぎの ことばの よみかたは どれですか。『午後』', 'MULTIPLE_CHOICE', 2, 0, '午後 = ごご (buổi chiều, p.m.). 午前 = ごぜん (buổi sáng, a.m.).', NOW() - INTERVAL 136800 MINUTE, 0, 'VOCABULARY', NULL),
  (20013, 20002, '「わたし ＿＿＿ ベトナムから きました。」', 'MULTIPLE_CHOICE', 1, 0, 'は đánh dấu chủ đề câu: "Tôi thì đến từ Việt Nam". を chỉ tân ngữ, không đi với 来ます theo nghĩa này.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20014, 20002, '「としょかん ＿＿＿ ほんを よみます。」', 'MULTIPLE_CHOICE', 1, 0, 'で chỉ nơi hành động diễn ra. Có động từ hành động (đọc sách) thì dùng で, không dùng に.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20015, 20002, '「まいばん １１じ ＿＿＿ ねます。」', 'MULTIPLE_CHOICE', 1, 0, 'Giờ cụ thể + に: 11じに ねます. Chú ý まいばん (mỗi tối) thì KHÔNG thêm に.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20016, 20002, '「あした いっしょに えいがを ＿＿＿か。」', 'MULTIPLE_CHOICE', 2, 0, 'Vませんか = lời mời lịch sự "…cùng … không?". あした (ngày mai) nên không thể là quá khứ みました.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20017, 20002, '「すみません、しおを ＿＿＿ください。」', 'MULTIPLE_CHOICE', 1, 0, 'Nhờ vả: Vて ください. とる → とって.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20018, 20002, '「きのうは さむく ＿＿＿。」', 'MULTIPLE_CHOICE', 2, 0, 'Tính từ い phủ định quá khứ: さむい → さむくなかったです. Không được nói さむいでした hay さむくでした.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20019, 20002, '「この りんごは あの りんご ＿＿＿ おおきいです。」', 'MULTIPLE_CHOICE', 2, 0, 'A は B より + tính từ = A … hơn B. ほど chỉ dùng trong câu phủ định: A は B ほど おおきくない.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20020, 20002, '「にほんごの べんきょうは ＿＿＿ですか。」「おもしろいです。」', 'MULTIPLE_CHOICE', 1, 0, 'Hỏi cảm nhận, đánh giá → どうですか (thế nào?).', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20021, 20002, '「へやに だれ ＿＿＿ いません。」', 'MULTIPLE_CHOICE', 2, 0, 'Từ để hỏi + も + phủ định = hoàn toàn không: だれも いません (không có ai cả).', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20022, 20002, 'つぎの ぶんの ★ に 入る ものは どれですか。
すみません、＿＿＿ ＿＿＿ ★ ＿＿＿ か。
（トイレ ／ は ／ どこ ／ です）', 'SENTENCE_ORDERING', 2, 0, 'Câu đúng: すみません、トイレ は どこ です か。Ô ★ là ô thứ ba → どこ.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20023, 20002, 'つぎの ぶんの ★ に 入る ものは どれですか。
きのう ＿＿＿ ＿＿＿ ★ ＿＿＿ ました。
（こうえん ／ で ／ ともだちと ／ あそび）', 'SENTENCE_ORDERING', 3, 0, 'Câu đúng: きのう こうえん で ともだちと あそび ました。Nơi chốn + で đứng trước, động từ ghép với ました ở cuối.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20024, 20002, '「わたしは ねこが ＿＿＿です。」', 'MULTIPLE_CHOICE', 1, 0, 'Tính từ な đứng cuối câu trước です thì bỏ な: すきです. すきな chỉ dùng khi đứng trước danh từ: すきな たべもの.', NOW() - INTERVAL 136800 MINUTE, 0, 'GRAMMAR', NULL),
  (20025, 20003, '田中さんは 3時までに 何を しますか。', 'MULTIPLE_CHOICE', 2, 0, 'Mẩu nhắn yêu cầu "trước cuộc họp (3 giờ), hãy photo 10 tờ tài liệu". Việc phải làm trước 3 giờ là photo.', NOW() - INTERVAL 136800 MINUTE, 0, 'READING', 20001),
  (20026, 20003, '山田さんは 何時ごろ 会社に もどりますか。', 'MULTIPLE_CHOICE', 1, 0, '「2時半ごろ 会社に もどります」— khoảng 2 giờ rưỡi. 3 giờ là giờ họp, dễ nhầm.', NOW() - INTERVAL 136800 MINUTE, 0, 'READING', 20001),
  (20027, 20003, 'グエンさんは ごご 何を しますか。', 'MULTIPLE_CHOICE', 1, 0, '「ごごは スーパーで アルバイトを します」. Đá bóng là việc cuối tuần, học là buổi sáng.', NOW() - INTERVAL 136800 MINUTE, 0, 'READING', 20002),
  (20028, 20003, 'ただしい ものは どれですか。', 'MULTIPLE_CHOICE', 2, 0, 'Bài viết 「電車で 学校へ 行きます」. Trường học từ 9 giờ đến 1 giờ, làm thêm buổi chiều, và Nguyễn đến từ Hà Nội.', NOW() - INTERVAL 136800 MINUTE, 0, 'READING', 20002),
  (20029, 20003, '学校は 何時間 ありますか。', 'MULTIPLE_CHOICE', 2, 0, 'Từ 9 giờ đến 1 giờ chiều là 4 tiếng. Dạng câu tính toán từ hai mốc giờ rất hay gặp ở N5.', NOW() - INTERVAL 136800 MINUTE, 0, 'READING', 20002),
  (20030, 20004, 'つぎの ことばの 読み方は どれですか。『急ぐ』', 'MULTIPLE_CHOICE', 2, 0, '急ぐ = いそぐ (vội). Âm Hán của 急 là キュウ: 急行 きゅうこう (tàu nhanh).', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20031, 20004, 'つぎの ことばの 読み方は どれですか。『説明』', 'MULTIPLE_CHOICE', 3, 0, '説明 = せつめい (giải thích). 明 có hai âm メイ và ミョウ — trong 説明 đọc メイ.', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20032, 20004, '「ねつが あるので、きょうは 会社を ＿＿＿。」', 'MULTIPLE_CHOICE', 2, 0, 'Bị sốt → nghỉ làm hôm nay: 会社を 休みます. 会社を やめます là nghỉ việc hẳn — quá mức với một cơn sốt.', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20033, 20004, '「この しりょうを 2まい ＿＿＿して ください。」', 'MULTIPLE_CHOICE', 2, 0, '"2 tờ" + tài liệu → photo 2 bản. Các từ còn lại không đi với số tờ theo nghĩa này.', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20034, 20004, '「家を 出るのが おそく なって、電車に ＿＿＿。」', 'MULTIPLE_CHOICE', 3, 0, 'Ra khỏi nhà muộn → không kịp tàu: 電車に 間に合わない. Đây là cặp từ hay ra: 間に合う (kịp) ↔ 遅れる (trễ).', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20035, 20004, 'つぎの ことばの 読み方は どれですか。『約束』', 'MULTIPLE_CHOICE', 2, 0, '約束 = やくそく (hẹn, lời hứa). Không biến âm thành ぞく.', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20036, 20004, '「あの 店は いつも 人が 多くて ＿＿＿です。」', 'MULTIPLE_CHOICE', 2, 0, 'Đông người → にぎやか (náo nhiệt). ていねい (lịch sự) hay しんせつ (tốt bụng) nói về cách phục vụ, không liên quan việc đông.', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20037, 20004, '「母は 料理が じょうずです。」と だいたい 同じ 意味の 文は どれですか。', 'MULTIPLE_CHOICE', 3, 0, 'じょうず ≈ うまい (giỏi). "Thích nấu" hay "hay nấu" không có nghĩa là nấu giỏi.', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20038, 20004, 'つぎの ことばの 読み方は どれですか。『準備』', 'MULTIPLE_CHOICE', 3, 0, '準備 = じゅんび (chuẩn bị).', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20039, 20004, '「さいふを ＿＿＿ しまいました。交番に 行きます。」', 'MULTIPLE_CHOICE', 2, 0, 'Đi đồn cảnh sát (交番) sau khi làm gì với ví → đánh rơi: 落として しまいました. てしまう diễn tả việc lỡ xảy ra, đáng tiếc.', NOW() - INTERVAL 132480 MINUTE, 0, 'VOCABULARY', NULL),
  (20040, 20005, '「日本へ 行ったら、ふじさんに ＿＿＿と 思って います。」', 'MULTIPLE_CHOICE', 2, 0, 'Dự định: Vよう（thể ý chí）と 思って います. 登る → 登ろう. 登れ là thể mệnh lệnh.', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20041, 20005, '「すみません、この 漢字、＿＿＿か。わたしは 読めないんです。」', 'MULTIPLE_CHOICE', 2, 0, 'Hỏi người khác có ĐỌC ĐƯỢC không → thể khả năng 読めます. 読ませます là bắt/cho ai đọc.', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20042, 20005, '「雨が ＿＿＿、しあいは 中止です。」', 'MULTIPLE_CHOICE', 2, 0, 'Điều kiện "nếu mưa thì trận đấu huỷ" → たら. 降っても nghĩa ngược lại (dù mưa vẫn…).', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20043, 20005, '「先生に しゅくだいを ＿＿＿。」', 'MULTIPLE_CHOICE', 3, 0, 'Người nhận ơn là mình, người làm là thầy (được đánh dấu bằng に) → Vて いただきました. くださる / くれる phải dùng が: 先生が 見て くださいました.', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20044, 20005, '「子どもの ころ、きらいな 野菜を 母に ＿＿＿。」', 'MULTIPLE_CHOICE', 4, 0, 'Bị bắt phải làm việc mình không muốn → thể bị động sai khiến 食べさせられる. Chữ "きらいな" là manh mối.', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20045, 20005, '「この 本は 字が 大きいので、読み ＿＿＿です。」', 'MULTIPLE_CHOICE', 2, 0, 'Chữ to → dễ đọc: V(bỏ ます)＋やすい. にくい là khó.', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20046, 20005, '「あしたは 雨が 降る ＿＿＿です。天気予報で 言って いました。」', 'MULTIPLE_CHOICE', 3, 0, 'Truyền đạt lại thông tin nghe được: thể thường ＋ そうです. Khác với 降りそうです (trông như sắp mưa).', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20047, 20005, '「ドアが ＿＿＿ います。だれか 開けたんでしょう。」', 'MULTIPLE_CHOICE', 3, 0, 'Trạng thái còn lại của sự việc, tự động từ ＋ て います: ドアが 開いて います. Tha động từ 開ける đi với を.', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20048, 20005, '「この かばんは ＿＿＿、買えません。」', 'MULTIPLE_CHOICE', 2, 0, 'Chỉ nguyên nhân rồi nối vế sau → thể て: 高すぎて 買えません (đắt quá nên không mua được).', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20049, 20005, 'つぎの 文の ★ に 入る ものは どれですか。
この 仕事は ＿＿＿ ＿＿＿ ★ ＿＿＿ ください。
（あした ／ までに ／ 必ず ／ 終わらせて）', 'SENTENCE_ORDERING', 3, 0, 'Câu đúng: この仕事は あした までに 必ず 終わらせて ください。Phó từ 必ず đứng ngay trước động từ.', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20050, 20005, '「部長は もう お帰りに ＿＿＿。」', 'MULTIPLE_CHOICE', 3, 0, 'Tôn kính ngữ: お＋V(bỏ ます)＋に なる. いたす / まいる là khiêm nhường ngữ, không dùng cho cấp trên.', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20051, 20005, '「重そうですね。わたしが お荷物を ＿＿＿。」', 'MULTIPLE_CHOICE', 3, 0, 'Mình làm cho người khác → khiêm nhường ngữ お＋V(bỏ ます)＋する: お持ちします.', NOW() - INTERVAL 132480 MINUTE, 0, 'GRAMMAR', NULL),
  (20052, 20006, 'パーティーの 場所は どうして かわりましたか。', 'MULTIPLE_CHOICE', 2, 0, '「予約が いっぱいだったので」→ không đặt được chỗ. Thời gian 「同じ」 nên không đổi.', NOW() - INTERVAL 132480 MINUTE, 0, 'READING', 20003),
  (20053, 20006, 'リンさんは 金曜日の 6時半に どこへ 行けば いいですか。', 'MULTIPLE_CHOICE', 2, 0, 'Kimura rủ 「6時半に 駅の 北口で 待ち合わせ」. 7 giờ mới là giờ bắt đầu ở quán.', NOW() - INTERVAL 132480 MINUTE, 0, 'READING', 20003),
  (20054, 20006, 'この お知らせの 内容と 合う ものは どれですか。', 'MULTIPLE_CHOICE', 2, 0, 'Tạp chí chỉ đọc tại thư viện, không cho mượn về. Sách mượn 2 tuần, tối đa 10 cuốn.', NOW() - INTERVAL 132480 MINUTE, 0, 'READING', 20004),
  (20055, 20006, '3日 おくれて 本を 返した 人は、いつから また 本を 借りられますか。', 'MULTIPLE_CHOICE', 3, 0, 'Trả trễ thì "từ ngày trả, trong 1 tuần không được mượn" — không phụ thuộc trễ bao nhiêu ngày.', NOW() - INTERVAL 132480 MINUTE, 0, 'READING', 20004),
  (20056, 20007, '次の 言葉の 読み方として 最も よい ものは どれか。『招待』', 'MULTIPLE_CHOICE', 3, 0, '招待 = しょうたい (mời). Hay nhầm với 正体 しょうたい (bộ mặt thật) — cùng cách đọc, khác chữ.', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20057, 20007, '次の 言葉の 読み方として 最も よい ものは どれか。『効果』', 'MULTIPLE_CHOICE', 3, 0, '効果 = こうか (hiệu quả). 果 đọc カ: 結果 けっか.', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20058, 20007, '「新しい 仕事に まだ ＿＿＿ いないので、毎日 疲れる。」', 'MULTIPLE_CHOICE', 3, 0, 'Việc mới, chưa QUEN nên mệt → 慣れて いない. 飽きる là chán — không hợp với "việc mới".', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20059, 20007, '「約束の 時間に ＿＿＿ しまい、友だちを 30分も 待たせた。」', 'MULTIPLE_CHOICE', 3, 0, 'Để bạn đợi 30 phút → đến trễ: 遅れて しまい.', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20060, 20007, '「部屋を ＿＿＿ 片付けたら、気持ちが よく なった。」', 'MULTIPLE_CHOICE', 4, 0, 'すっかり = hoàn toàn, sạch sẽ. うっかり là lơ đễnh, がっかり là thất vọng, のんびり là thong thả.', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20061, 20007, '「会議は 延期に なった。」と 意味が 最も 近い ものは どれか。', 'MULTIPLE_CHOICE', 4, 0, '延期 = hoãn sang ngày khác. 中止 là huỷ hẳn — hai từ này rất hay bị đặt cạnh nhau để gài bẫy.', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20062, 20007, '次の 言葉の 読み方として 最も よい ものは どれか。『乗り換える』', 'MULTIPLE_CHOICE', 3, 0, '乗り換える = のりかえる (đổi tàu). 乗り換え (danh từ) cũng đọc のりかえ, không biến âm.', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20063, 20007, '「弟は ＿＿＿ 性格で、だれとでも すぐ 友だちに なる。」', 'MULTIPLE_CHOICE', 3, 0, 'Kết bạn nhanh với bất kỳ ai → tính cách 明るい (vui vẻ, cởi mở).', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20064, 20008, '「日本に 来た ＿＿＿、日本語が ぜんぜん わからなかった。」', 'MULTIPLE_CHOICE', 3, 0, 'Vた ばかり = vừa mới. 来たばかりの ころは = hồi mới đến. うちに / あいだに không đi với thể た theo nghĩa này.', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20065, 20008, '「雨が 降り ＿＿＿だから、かさを 持って 行きなさい。」', 'MULTIPLE_CHOICE', 3, 0, 'Chỉ そう mới gắn vào gốc động từ bỏ ます: 降りそう (trông như sắp mưa). よう / らしい / みたい đi với thể thường: 降るようだ.', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20066, 20008, '「この レストランは 値段が 安い ＿＿＿、とても おいしい。」', 'MULTIPLE_CHOICE', 4, 0, 'わりに = so với … thì (hơn mong đợi). くせに mang ý chê trách, không hợp với lời khen.', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20067, 20008, '「子どもの ＿＿＿、よく この 川で 泳いだ ものだ。」', 'MULTIPLE_CHOICE', 3, 0, '〜の ころ ＋ たものだ = hồi còn … thường hay … (hoài niệm).', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20068, 20008, '「急いで いた ＿＿＿、財布を 家に 忘れて しまった。」', 'MULTIPLE_CHOICE', 3, 0, 'Nguyên nhân dẫn tới kết quả xấu → せいで. おかげで dùng cho kết quả tốt.', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20069, 20008, '「天気予報 ＿＿＿、午後から 雪が 降るそうだ。」', 'MULTIPLE_CHOICE', 3, 0, 'Nguồn tin + によると ＋ 〜そうだ (theo … thì nghe nói). について là "về", にとって là "đối với".', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20070, 20008, '「この 仕事は 私 ＿＿＿ 難しすぎる。」', 'MULTIPLE_CHOICE', 3, 0, 'Đánh giá từ góc nhìn của ai → にとって (đối với tôi).', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20071, 20008, '「どんなに 練習 ＿＿＿、上手に ならない。」', 'MULTIPLE_CHOICE', 3, 0, 'どんなに 〜ても = dù … đến mấy cũng. どんなに luôn đi với ても.', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20072, 20008, '次の 文の ★ に 入る 最も よい ものは どれか。
彼女は ＿＿＿ ＿＿＿ ★ ＿＿＿ いる。
（医者に ／ なる ／ ために ／ 勉強して）', 'SENTENCE_ORDERING', 4, 0, 'Câu đúng: 彼女は 医者に なる ために 勉強して いる。Vる ＋ ために = để (mục đích).', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20073, 20008, '「担当の 者が 参りますので、こちらで 少々 ＿＿＿ ください。」', 'MULTIPLE_CHOICE', 3, 0, 'Mời khách: お＋V(bỏ ます)＋ください → お待ち ください.', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20074, 20009, 'この 文章で 筆者が 一番 言いたい ことは 何か。', 'MULTIPLE_CHOICE', 3, 0, 'Ý chính nằm ở câu cuối 「使う場所と時間を考えることが大切だ」. Bài không khuyên bỏ hẳn điện thoại.', NOW() - INTERVAL 126720 MINUTE, 0, 'READING', 20005),
  (20075, 20009, '調査で わかった ことは 何か。', 'MULTIPLE_CHOICE', 3, 0, '3割 là tỉ lệ trong số VỤ BỊ THƯƠNG, không phải tỉ lệ người đi đường. Đáp án thứ hai là bẫy đổi chủ thể.', NOW() - INTERVAL 126720 MINUTE, 0, 'READING', 20005),
  (20076, 20009, '筆者が ジョギングを 続けて 変わった ことは 何か。', 'MULTIPLE_CHOICE', 3, 0, '「仕事中も 眠く ならなく なった」. Việc dậy sớm thấy khổ là chuyện lúc MỚI bắt đầu.', NOW() - INTERVAL 126720 MINUTE, 0, 'READING', 20006),
  (20077, 20009, '筆者の 考えに 合う ものは どれか。', 'MULTIPLE_CHOICE', 3, 0, 'Câu kết nêu quan điểm: tạo thói quen thì cần cố gắng tháng đầu tiên.', NOW() - INTERVAL 126720 MINUTE, 0, 'READING', 20006),
  (20078, 20010, '「雨 ＿＿＿、試合は 予定通り 行われた。」', 'MULTIPLE_CHOICE', 4, 0, 'にもかかわらず = mặc dù (kết quả trái với dự đoán). Mưa nhưng vẫn thi đấu đúng lịch.', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20079, 20010, '「毎日 努力した ＿＿＿、第一志望の 大学に 合格できた。」', 'MULTIPLE_CHOICE', 4, 0, 'かいがあって = công sức không uổng, nhờ đó mà có kết quả tốt. あげく dùng cho kết cục xấu sau thời gian dài.', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20080, 20010, '「この 仕事は 年齢や 経験 ＿＿＿、誰でも 応募できる。」', 'MULTIPLE_CHOICE', 4, 0, 'を問わず = không kể, bất kể. Hay đi với các cặp từ đối lập: 年齢を問わず, 男女を問わず.', NOW() - INTERVAL 126720 MINUTE, 0, 'GRAMMAR', NULL),
  (20081, 20010, '次の 言葉の 読み方として 最も よい ものは どれか。『把握』', 'MULTIPLE_CHOICE', 4, 0, '把握 = はあく (nắm bắt). Từ văn viết rất hay gặp trong đề đọc hiểu N2.', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20082, 20010, '次の 言葉の 読み方として 最も よい ものは どれか。『妥協』', 'MULTIPLE_CHOICE', 5, 0, '妥協 = だきょう (thoả hiệp). Không có âm ngắt っ.', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL),
  (20083, 20010, '「全員が 参加できるように、会議の 日程を ＿＿＿した。」', 'MULTIPLE_CHOICE', 5, 0, '調整 = điều chỉnh cho các bên khớp nhau (lịch, ý kiến). 調節 dùng cho mức độ vật lý: 温度を調節する.', NOW() - INTERVAL 126720 MINUTE, 0, 'VOCABULARY', NULL);
