INSERT INTO VocabItems (VocabID, Word, Reading, Meaning, PartOfSpeech, LevelID, ExampleSentence, ExampleMeaning, CreatedAt) VALUES
  (20001, '急ぐ', 'いそぐ', 'vội, gấp', 'động từ', 2, '時間が ないので 急いで ください。', 'Không có thời gian nên hãy nhanh lên.', NOW() - INTERVAL 129600 MINUTE),
  (20002, '説明', 'せつめい', 'giải thích', 'danh từ', 2, '先生の 説明は わかりやすいです。', 'Lời giải thích của thầy dễ hiểu.', NOW() - INTERVAL 129600 MINUTE),
  (20003, '準備', 'じゅんび', 'chuẩn bị', 'danh từ', 2, '旅行の 準備を して います。', 'Tôi đang chuẩn bị cho chuyến du lịch.', NOW() - INTERVAL 129600 MINUTE),
  (20004, '約束', 'やくそく', 'lời hứa, cuộc hẹn', 'danh từ', 2, '友だちと 3時に 会う 約束が あります。', 'Tôi có hẹn gặp bạn lúc 3 giờ.', NOW() - INTERVAL 129600 MINUTE),
  (20005, '予約', 'よやく', 'đặt trước', 'danh từ', 2, 'レストランを 予約しました。', 'Tôi đã đặt bàn ở nhà hàng.', NOW() - INTERVAL 129600 MINUTE),
  (20006, '経験', 'けいけん', 'kinh nghiệm', 'danh từ', 2, '日本で 働いた 経験が あります。', 'Tôi có kinh nghiệm làm việc ở Nhật.', NOW() - INTERVAL 129600 MINUTE),
  (20007, '会議', 'かいぎ', 'cuộc họp', 'danh từ', 2, '会議は 10時から です。', 'Cuộc họp bắt đầu từ 10 giờ.', NOW() - INTERVAL 129600 MINUTE),
  (20008, '資料', 'しりょう', 'tài liệu', 'danh từ', 2, '会議の 資料を コピーします。', 'Tôi photo tài liệu cuộc họp.', NOW() - INTERVAL 129600 MINUTE),
  (20009, '遅れる', 'おくれる', 'trễ, muộn', 'động từ', 2, '電車が 遅れて います。', 'Tàu điện đang bị trễ.', NOW() - INTERVAL 129600 MINUTE),
  (20010, '間に合う', 'まにあう', 'kịp', 'động từ', 2, 'タクシーで 行けば 間に合います。', 'Đi taxi thì sẽ kịp.', NOW() - INTERVAL 129600 MINUTE),
  (20011, '落とす', 'おとす', 'đánh rơi', 'động từ', 2, 'かぎを 落として しまいました。', 'Tôi lỡ đánh rơi chìa khoá.', NOW() - INTERVAL 129600 MINUTE),
  (20012, '拾う', 'ひろう', 'nhặt', 'động từ', 2, '道で さいふを 拾いました。', 'Tôi nhặt được ví trên đường.', NOW() - INTERVAL 129600 MINUTE),
  (20013, '届ける', 'とどける', 'giao đến, mang đến', 'động từ', 2, '荷物を 家まで 届けます。', 'Chúng tôi giao hàng tận nhà.', NOW() - INTERVAL 129600 MINUTE),
  (20014, '集める', 'あつめる', 'thu thập, sưu tầm', 'động từ', 2, '古い 切手を 集めて います。', 'Tôi sưu tầm tem cũ.', NOW() - INTERVAL 129600 MINUTE),
  (20015, '決める', 'きめる', 'quyết định', 'động từ', 2, '旅行の 日を 決めましょう。', 'Hãy quyết định ngày đi du lịch.', NOW() - INTERVAL 129600 MINUTE),
  (20016, '続ける', 'つづける', 'tiếp tục', 'động từ', 2, '毎日 日本語の 勉強を 続けて います。', 'Ngày nào tôi cũng tiếp tục học tiếng Nhật.', NOW() - INTERVAL 129600 MINUTE),
  (20017, '片付ける', 'かたづける', 'dọn dẹp', 'động từ', 2, '使った ものは 片付けて ください。', 'Đồ đã dùng thì hãy dọn lại.', NOW() - INTERVAL 129600 MINUTE),
  (20018, '引っ越す', 'ひっこす', 'chuyển nhà', 'động từ', 2, '来月 大阪に 引っ越します。', 'Tháng sau tôi chuyển nhà đến Osaka.', NOW() - INTERVAL 129600 MINUTE),
  (20019, '楽しみ', 'たのしみ', 'niềm vui, mong chờ', 'danh từ', 2, '夏休みが 楽しみです。', 'Tôi rất mong kỳ nghỉ hè.', NOW() - INTERVAL 129600 MINUTE),
  (20020, '趣味', 'しゅみ', 'sở thích', 'danh từ', 2, '私の 趣味は 写真を とる ことです。', 'Sở thích của tôi là chụp ảnh.', NOW() - INTERVAL 129600 MINUTE),
  (20021, '丁寧', 'ていねい', 'lịch sự, cẩn thận', 'tính từ な', 2, '店員が 丁寧に 説明して くれました。', 'Nhân viên đã giải thích rất lịch sự.', NOW() - INTERVAL 129600 MINUTE),
  (20022, '親切', 'しんせつ', 'tốt bụng', 'tính từ な', 2, '隣の 人は とても 親切です。', 'Người hàng xóm rất tốt bụng.', NOW() - INTERVAL 129600 MINUTE),
  (20023, '複雑', 'ふくざつ', 'phức tạp', 'tính từ な', 2, 'この 問題は 複雑です。', 'Vấn đề này phức tạp.', NOW() - INTERVAL 129600 MINUTE),
  (20024, '簡単', 'かんたん', 'đơn giản', 'tính từ な', 2, 'この 料理は 作り方が 簡単です。', 'Món này cách làm đơn giản.', NOW() - INTERVAL 129600 MINUTE),
  (20025, '必要', 'ひつよう', 'cần thiết', 'tính từ な', 2, 'パスポートが 必要です。', 'Cần có hộ chiếu.', NOW() - INTERVAL 129600 MINUTE),
  (20026, '特に', 'とくに', 'đặc biệt là', 'phó từ', 2, '日本料理の 中で 特に すしが 好きです。', 'Trong các món Nhật, tôi đặc biệt thích sushi.', NOW() - INTERVAL 129600 MINUTE),
  (20027, '必ず', 'かならず', 'nhất định, chắc chắn', 'phó từ', 2, '明日は 必ず 来て ください。', 'Ngày mai nhất định hãy đến nhé.', NOW() - INTERVAL 129600 MINUTE),
  (20028, '最近', 'さいきん', 'gần đây', 'danh từ', 2, '最近 寒く なりましたね。', 'Gần đây trời lạnh hẳn rồi nhỉ.', NOW() - INTERVAL 129600 MINUTE),
  (20029, '途中', 'とちゅう', 'giữa chừng, dọc đường', 'danh từ', 2, '会社へ 行く 途中で 銀行に 寄ります。', 'Trên đường đi làm tôi ghé ngân hàng.', NOW() - INTERVAL 129600 MINUTE),
  (20030, '都合', 'つごう', 'sự thuận tiện (thời gian)', 'danh từ', 2, '明日の 都合は どうですか。', 'Ngày mai anh có tiện không?', NOW() - INTERVAL 129600 MINUTE),
  (20031, '招待', 'しょうたい', 'mời', 'danh từ', 3, '結婚式に 招待されました。', 'Tôi được mời dự đám cưới.', NOW() - INTERVAL 129600 MINUTE),
  (20032, '効果', 'こうか', 'hiệu quả', 'danh từ', 3, 'この 薬は すぐに 効果が 出ます。', 'Thuốc này có hiệu quả ngay.', NOW() - INTERVAL 129600 MINUTE),
  (20033, '延期', 'えんき', 'hoãn lại', 'danh từ', 3, '雨で 試合が 延期に なった。', 'Trận đấu bị hoãn vì mưa.', NOW() - INTERVAL 129600 MINUTE),
  (20034, '中止', 'ちゅうし', 'huỷ bỏ', 'danh từ', 3, '台風で イベントは 中止だ。', 'Sự kiện bị huỷ vì bão.', NOW() - INTERVAL 129600 MINUTE),
  (20035, '慣れる', 'なれる', 'quen với', 'động từ', 3, '日本の 生活に もう 慣れました。', 'Tôi đã quen với cuộc sống ở Nhật.', NOW() - INTERVAL 129600 MINUTE),
  (20036, '迷う', 'まよう', 'lạc đường, phân vân', 'động từ', 3, 'どちらに するか 迷って いる。', 'Tôi đang phân vân chọn cái nào.', NOW() - INTERVAL 129600 MINUTE),
  (20037, '増える', 'ふえる', 'tăng lên', 'động từ', 3, '外国人の 観光客が 増えて いる。', 'Khách du lịch nước ngoài đang tăng.', NOW() - INTERVAL 129600 MINUTE),
  (20038, '減る', 'へる', 'giảm đi', 'động từ', 3, '最近 体重が 減った。', 'Gần đây cân nặng của tôi giảm.', NOW() - INTERVAL 129600 MINUTE),
