  (20040, '関係', 'かんけい', 'quan hệ, liên quan', 'danh từ', 3, 'その 話は 私には 関係ない。', 'Chuyện đó không liên quan đến tôi.', NOW() - INTERVAL 129600 MINUTE),
  (20041, '習慣', 'しゅうかん', 'thói quen, tập quán', 'danh từ', 3, '寝る 前に 本を 読む 習慣が ある。', 'Tôi có thói quen đọc sách trước khi ngủ.', NOW() - INTERVAL 129600 MINUTE),
  (20042, '集中', 'しゅうちゅう', 'tập trung', 'danh từ', 3, 'うるさくて 集中できない。', 'Ồn quá không tập trung được.', NOW() - INTERVAL 129600 MINUTE),
