  (20012, 4, 'tt-gv-01', 'N2 · Ngữ pháp & từ vựng trọng tâm', 15, NULL, NULL, 0, NOW() - INTERVAL 72000 MINUTE, NULL, 1, 1, 0, 0, 0, 1),
