INSERT INTO ExamSections (SectionID, ExamID, Name, DurationMinutes, OrderNo, CreatedAt) VALUES
  (20001, 20004, '言語知識（文字・語彙）', 20, 1, NOW() - INTERVAL 86400 MINUTE),
  (20002, 20004, '言語知識（文法）・読解', 40, 2, NOW() - INTERVAL 86400 MINUTE),
