INSERT INTO Courses (CourseID, Title, Description, LevelID, AuthorID, Status, ReviewedBy, ReviewedAt, ReviewNote, CreatedAt, UpdatedAt) VALUES
  (20001, 'Lộ trình N5 — Nền tảng trong 6 tuần', 'Đi từ câu です đầu tiên tới đề thi thử N5: ngữ pháp cốt lõi, 20 chữ Hán chỉ thời gian, và kỹ năng đọc hiểu cơ bản.', 1, 'tt-gv-03', 'PUBLISHED', 'tt-admin-01', NOW() - INTERVAL 100800 MINUTE, NULL, NOW() - INTERVAL 122400 MINUTE, NOW() - INTERVAL 100860 MINUTE),
  (20002, 'Lộ trình N4 — Ngữ pháp trọng tâm', 'Năm nhóm ngữ pháp chiếm phần lớn điểm 文法 của N4: thể ý chí, thể khả năng, điều kiện, bị động – sai khiến và kính ngữ.', 2, 'tt-gv-02', 'PUBLISHED', 'tt-admin-01', NOW() - INTERVAL 93600 MINUTE, NULL, NOW() - INTERVAL 115200 MINUTE, NOW() - INTERVAL 93660 MINUTE),
  (20003, 'Lộ trình N3 — Đọc hiểu không sợ bài dài', 'Chiến thuật đọc câu hỏi trước, nhận ra ý chính qua liên từ, và luyện với bài nghị luận ngắn đúng dạng đề N3.', 3, 'tt-gv-01', 'PUBLISHED', 'tt-admin-01', NOW() - INTERVAL 57600 MINUTE, NULL, NOW() - INTERVAL 86400 MINUTE, NOW() - INTERVAL 57660 MINUTE),
  (20004, 'Lộ trình N2 — Ngữ pháp văn viết', 'Các mẫu ngữ pháp văn viết hay ra ở N2: nhượng bộ, phạm vi, kết quả.', 4, 'tt-gv-01', 'PENDING', NULL, NULL, NULL, NOW() - INTERVAL 8640 MINUTE, NOW() - INTERVAL 8700 MINUTE),
  (20005, 'N4 — Kính ngữ trong công việc', 'Kính ngữ dùng hằng ngày ở công ty Nhật: nói với cấp trên, với khách hàng, qua điện thoại.', 2, 'tt-gv-02', 'REJECTED', 'tt-admin-01', NOW() - INTERVAL 4320 MINUTE, 'Bài 2 và bài 3 đang trùng nội dung về 尊敬語. Tách rõ 尊敬語 và 謙譲語 thành hai bài, thêm ví dụ hội thoại nơi công sở rồi gửi lại.', NOW() - INTERVAL 17280 MINUTE, NOW() - INTERVAL 4380 MINUTE),
  (20006, 'Lộ trình N5 — Luyện nghe cơ bản', 'Nghe số đếm, giờ giấc và hội thoại ngắn hằng ngày. Đang soạn.', 1, 'tt-gv-04', 'DRAFT', NULL, NULL, NULL, NOW() - INTERVAL 2880 MINUTE, NOW() - INTERVAL 2940 MINUTE);
INSERT INTO CourseLessons (LessonID, CourseID, OrderNo, Title, LessonType, Content, EstimatedMinutes, DeckID, ExamID, CreatedAt, MinScorePercent) VALUES
  (20001, 20001, 1, 'Chặng 1 · Câu です — khẳng định, phủ định, nghi vấn', 'GRAMMAR', 'CẤU TRÚC
N1 は N2 です。 — N1 là N2.
N1 は N2 じゃありません ／ ではありません。 — N1 không phải là N2.
N1 は N2 ですか。 — N1 có phải là N2 không?

VÍ DỤ
わたしは ベトナムじんです。 — Tôi là người Việt Nam.
リンさんは がくせいじゃありません。かいしゃいんです。 — Chị Linh không phải sinh viên, chị ấy là nhân viên công ty.
あの ひとは せんせいですか。 — Người kia là giáo viên phải không?
→ はい、そうです。／ いいえ、ちがいます。

GHI NHỚ
• は trong mẫu câu này đọc là "wa", không đọc "ha".
• か ở cuối câu biến câu thành câu hỏi. Không đảo trật tự từ như tiếng Anh.
• じゃありません dùng khi nói chuyện, ではありません trang trọng hơn, hay gặp trong văn viết.

LỖI NGƯỜI VIỆT HAY MẮC
Bỏ quên は: "わたし ベトナムじんです" nghe cụt. Tiếng Việt không có trợ từ chủ đề nên rất dễ quên — hãy tập nói trọn cả câu.', 15, NULL, NULL, NOW() - INTERVAL 122400 MINUTE, NULL),
  (20002, 20001, 2, 'Chặng 2 · Từ vựng thời gian & địa điểm', 'VOCAB', 'Chặng này học bằng thẻ ghi nhớ.

CÁCH HỌC HIỆU QUẢ
1. Mỗi ngày mở bộ thẻ, ôn hết số thẻ đến hạn trước rồi mới học thẻ mới.
2. Đọc to cả từ và câu ví dụ. Nhớ từ trong câu thì dùng được, nhớ từ đứng một mình thì chỉ nhận ra được.
3. Chấm thật lòng: nhớ mang máng thì chọn "Khó", đừng chọn "Tốt". Hệ thống dựa vào đó để hẹn ngày ôn lại.

NHÓM TỪ TRỌNG TÂM
• Thời gian: ごぜん (buổi sáng), ごご (buổi chiều), せんげつ (tháng trước)
• Địa điểm: ぎんこう (ngân hàng), こうえん (công viên), としょかん (thư viện)
• Động từ đi cặp: あける ↔ しめる (mở ↔ đóng)
• Tính từ trái nghĩa: おもい ↔ かるい (nặng ↔ nhẹ)

Mẹo: học theo cặp trái nghĩa thì nhớ được gấp đôi mà chỉ tốn công một lần.', 20, 20004, NULL, NOW() - INTERVAL 122400 MINUTE, NULL),
  (20003, 20001, 3, 'Chặng 3 · Trợ từ を・に・で・へ', 'GRAMMAR', 'Trợ từ là "khớp nối" của câu tiếng Nhật. Sai trợ từ là câu đổi nghĩa hoặc vô nghĩa.

を — đánh dấu tân ngữ
パンを たべます。 — Ăn bánh mì.

に — thời điểm cụ thể, đích đến, người nhận
7じに おきます。 — Dậy lúc 7 giờ.
ともだちに てがみを かきます。 — Viết thư cho bạn.

で — nơi diễn ra hành động, phương tiện
としょかんで べんきょうします。 — Học ở thư viện.
でんしゃで いきます。 — Đi bằng tàu điện.

へ — hướng di chuyển (đọc là "e")
にほんへ いきます。 — Đi Nhật.

PHÂN BIỆT に VÀ で KHI CHỈ NƠI CHỐN
• に: nơi SỰ VẬT TỒN TẠI → へやに ねこが います。
• で: nơi HÀNH ĐỘNG XẢY RA → へやで ほんを よみます。
Mẹo: có động từ hành động (ăn, học, chơi…) thì gần như luôn là で.

KIỂM TRA CHẶNG
Làm đề "N5 · Luyện ngữ pháp — Đề 1" và đạt từ 60% để mở chặng tiếp theo.', 20, NULL, 20002, NOW() - INTERVAL 122400 MINUTE, 60),
  (20004, 20001, 4, 'Chặng 4 · Chữ Hán chỉ thời gian', 'KANJI', '10 chữ Hán trong chặng này có mặt ở gần như mọi đề N5 vì chúng dùng để nói giờ giấc, ngày tháng.

BẢNG CHỮ
午 ゴ — trưa (NGỌ) → 午前 ごぜん buổi sáng, 午後 ごご buổi chiều
前 ゼン ／ まえ — trước (TIỀN) → 駅の前 えきのまえ trước nhà ga
後 ゴ ／ うしろ・あと — sau (HẬU)
週 シュウ — tuần (CHU) → 先週 せんしゅう tuần trước, 毎週 まいしゅう mỗi tuần
毎 マイ — mỗi (MỖI) → 毎日 まいにち mỗi ngày
今 コン ／ いま — bây giờ (KIM) → 今日 きょう hôm nay (cách đọc đặc biệt)
何 なに・なん — cái gì (HÀ) → 何時 なんじ mấy giờ
半 ハン — một nửa (BÁN) → 3時半 さんじはん ba giờ rưỡi
分 フン・プン — phút (PHÂN) → 5分 ごふん, 10分 じゅっぷん
本 ホン — sách, gốc (BẢN) → 日本 にほん Nhật Bản

CHÚ Ý BIẾN ÂM CỦA 分
Sau 2, 5, 7, 9 đọc ふん. Sau 1, 3, 4, 6, 8, 10 đọc ぷん: いっぷん, さんぷん, よんぷん, ろっぷん, はっぷん, じゅっぷん.', 20, 20005, NULL, NOW() - INTERVAL 122400 MINUTE, NULL),
  (20005, 20001, 5, 'Chặng 5 · Thể て — nhờ vả và nối câu', 'GRAMMAR', 'Thể て là dạng chia quan trọng nhất ở N5: nhờ vả, nối hành động, diễn tả việc đang làm đều bắt đầu từ nó.

CÁCH CHIA — ĐỘNG TỪ NHÓM 1
う・つ・る → って: かう → かって, まつ → まって, とる → とって
む・ぶ・ぬ → んで: よむ → よんで, あそぶ → あそんで
く → いて: かく → かいて (ngoại lệ: いく → いって)
ぐ → いで: いそぐ → いそいで
す → して: はなす → はなして

NHÓM 2: bỏ る thêm て → たべる → たべて
NHÓM 3: する → して, くる → きて

CÁCH DÙNG
1. Nhờ vả: Vて ください。 — まどを あけて ください。
2. Nối hành động theo thứ tự: あさ おきて、かおを あらって、がっこうへ いきます。
3. Đang làm: Vて います。 — いま、テレビを みて います。

LỖI HAY GẶP
Chia いく thành いいて. いく là ngoại lệ duy nhất của nhóm く → いって.', 20, NULL, NULL, NOW() - INTERVAL 122400 MINUTE, NULL),
  (20006, 20001, 6, 'Chặng 6 · Thi thử cuối lộ trình', 'READING', 'Chặng cuối là một đề thi thử theo đúng cấu trúc phần 言語知識 và 読解 của N5: hai phần, mỗi phần có đồng hồ riêng, hết giờ phần nào là khoá phần đó.

TRƯỚC KHI LÀM
• Chuẩn bị đủ 60 phút liền, không bị gián đoạn.
• Phần 1 (文字・語彙, 20 phút): đừng dừng quá lâu ở một câu chữ Hán. Không nhớ thì loại trừ rồi đi tiếp.
• Phần 2 (文法・読解, 40 phút): làm ngữ pháp nhanh để dành thời gian cho bài đọc.

KỸ NĂNG ĐỌC HIỂU N5
1. Đọc câu hỏi TRƯỚC rồi mới đọc đoạn văn — biết mình cần tìm gì thì đọc nhanh hơn.
2. Gạch chân giờ giấc, số lượng, địa điểm — đề N5 hay hỏi đúng những chi tiết này.
3. Đáp án đúng thường diễn đạt lại ý trong bài bằng từ khác. Đáp án lặp nguyên văn một cụm trong bài lại hay là bẫy.

Đạt từ 60% là hoàn thành lộ trình. Chưa đạt thì xem lại các câu sai trong sổ tay rồi làm lại — đề cho phép 2 lượt.', 60, NULL, 20004, NOW() - INTERVAL 122400 MINUTE, 60),
  (20007, 20002, 1, 'Chặng 1 · Thể ý chí — Vようと思っています', 'GRAMMAR', 'CÁCH CHIA
Nhóm 1: đổi đuôi sang hàng お ＋ う → いく → いこう, のむ → のもう, かえる → かえろう
Nhóm 2: bỏ る thêm よう → たべる → たべよう
Nhóm 3: する → しよう, くる → こよう

CÁCH DÙNG
1. Rủ rê thân mật: いっしょに かえろう。 — Cùng về đi.
2. Nói dự định: Vようと 思って います。
   来年、日本へ 留学しようと 思って います。 — Tôi đang định sang năm đi du học Nhật.

PHÂN BIỆT VỚI つもり
• Vようと思っています: dự định đang hình thành, còn có thể đổi.
• Vるつもりです: quyết tâm rõ hơn, đã tính kỹ.

BẪY TRONG ĐỀ
Đề hay đặt thể mệnh lệnh (行け, 飲め) cạnh thể ý chí (行こう, 飲もう) vì hai dạng này trông na ná. Nhìn nguyên âm cuối: お là ý chí, え là mệnh lệnh.', 20, NULL, NULL, NOW() - INTERVAL 115200 MINUTE, NULL),
  (20008, 20002, 2, 'Chặng 2 · Từ vựng công việc & sinh hoạt', 'VOCAB', 'Chặng này học bằng bộ thẻ 30 từ N4.

NHÓM TỪ
• Công việc: 会議, 資料, 予約, 経験, 説明, 準備
• Cặp động từ dễ nhầm: 遅れる (trễ) ↔ 間に合う (kịp), 落とす (đánh rơi) ↔ 拾う (nhặt)
• Tính từ な: 丁寧, 親切, 複雑, 簡単, 必要
• Phó từ: 特に (đặc biệt là), 必ず (nhất định)

GỢI Ý
Đề 文字・語彙 của N4 hỏi cả CÁCH ĐỌC lẫn CÁCH DÙNG. Khi ôn thẻ, đọc to câu ví dụ và tự đặt thêm một câu của riêng mình.', 20, 20001, NULL, NOW() - INTERVAL 115200 MINUTE, NULL),
  (20009, 20002, 3, 'Chặng 3 · Thể khả năng — có thể ／ không thể', 'GRAMMAR', 'CÁCH CHIA
Nhóm 1: đổi đuôi sang hàng え ＋ る → よむ → よめる, かく → かける, はなす → はなせる
Nhóm 2: bỏ る thêm られる → たべる → たべられる, みる → みられる
Nhóm 3: する → できる, くる → こられる

TRỢ TỪ ĐỔI THEO
Tân ngữ thường chuyển từ を sang が:
日本語を 話す → 日本語が 話せる

VÍ DỤ
この 漢字が 読めますか。 — Bạn đọc được chữ Hán này không?
忙しくて、パーティーに 行けません。 — Bận quá nên không đi dự tiệc được.

LỖI HAY GẶP
Nhầm 見える ／ 聞こえる (tự nhiên thấy, tự nhiên nghe) với 見られる ／ 聞ける (có khả năng xem, nghe). Từ đây nhìn ra núi Phú Sĩ → 富士山が 見えます, không nói 見られます.', 20, NULL, NULL, NOW() - INTERVAL 115200 MINUTE, NULL),
  (20010, 20002, 4, 'Chặng 4 · Điều kiện たら・ば・と', 'GRAMMAR', 'BA CÁCH NÓI "NẾU"

たら — dùng được nhiều nhất, cả điều kiện lẫn "sau khi"
雨が 降ったら、行きません。 — Nếu mưa thì tôi không đi.
駅に 着いたら、電話して ください。 — Tới ga thì gọi cho tôi.

ば — nhấn vào điều kiện cần
安ければ 買います。 — Nếu rẻ thì mua.

と — kết quả tất yếu, lặp lại (máy móc, tự nhiên, chỉ đường)
この ボタンを 押すと、ドアが 開きます。 — Bấm nút này là cửa mở.

MẸO CHỌN NHANH TRONG ĐỀ
• Vế sau là lời nhờ, lời mời, ý chí (ください, ましょう, つもり) → dùng たら, không dùng と.
• Vế sau là quy luật, kết quả tự nhiên → と.
• Còn phân vân thì たら đúng trong nhiều trường hợp nhất.', 25, NULL, NULL, NOW() - INTERVAL 115200 MINUTE, NULL),
  (20011, 20002, 5, 'Chặng 5 · Kính ngữ cơ bản & kiểm tra cuối lộ trình', 'GRAMMAR', 'HAI NHÓM KÍNH NGỮ

尊敬語 — nâng hành động của NGƯỜI KHÁC
お＋V(bỏ ます)＋に なる: 部長は もう お帰りに なりました。
Động từ đặc biệt: いらっしゃる (đi, đến, ở), 召し上がる (ăn, uống), おっしゃる (nói)

謙譲語 — hạ hành động của CHÍNH MÌNH
お＋V(bỏ ます)＋する: わたしが お持ちします。
Động từ đặc biệt: 参る (đi, đến), いただく (ăn, nhận), 申す (nói)

CÁCH KHÔNG BAO GIỜ NHẦM
Hỏi: hành động này của AI? Của người trên → 尊敬語. Của mình → 謙譲語.

KIỂM TRA
Làm đề "N4 · Luyện ngữ pháp trọng tâm" và đạt từ 70% để hoàn thành lộ trình. Ngưỡng cao hơn các chặng trước vì đây là chặng tổng kết.', 25, NULL, 20006, NOW() - INTERVAL 115200 MINUTE, 70),
  (20012, 20003, 1, 'Chặng 1 · Đọc câu hỏi trước, đọc bài sau', 'READING', 'Phần 読解 của N3 không thiếu thời gian nếu đọc có mục đích. Người mất điểm thường đọc kỹ từng chữ từ đầu tới cuối rồi mới xem câu hỏi.

QUY TRÌNH BA BƯỚC
1. Đọc câu hỏi và gạch chân từ khoá: 理由 (lý do), 筆者の考え (ý kiến tác giả), 何を (cái gì).
2. Đọc lướt đoạn văn, dừng lại ở chỗ chứa từ khoá hoặc liên từ đổi hướng (しかし, ところが).
3. Đối chiếu từng phương án với câu trong bài. Loại những phương án nói QUÁ MỨC bài viết (すべて, 必ず, 絶対).

CÂU HỎI "Ý KIẾN TÁC GIẢ"
Ý kiến thường nằm ở đoạn CUỐI, sau các cụm: 〜と思う, 〜べきだ, 〜ことが大切だ.', 15, NULL, NULL, NOW() - INTERVAL 86400 MINUTE, NULL),
  (20013, 20003, 2, 'Chặng 2 · Từ vựng chủ đề xã hội', 'VOCAB', '15 từ trong bộ thẻ này lặp lại rất nhiều trong bài đọc nghị luận N3: 増える ／ 減る, 調査, 関係, 習慣, 集中, 周り…

MẸO
Bài đọc N3 hay đưa số liệu khảo sát (調査によると…). Nắm chắc cặp 増える ↔ 減る và các từ chỉ tỉ lệ (割, 半分, 以上, 以下) là đã gỡ được nhiều câu hỏi chi tiết.', 20, 20002, NULL, NOW() - INTERVAL 86400 MINUTE, NULL),
  (20014, 20003, 3, 'Chặng 3 · Liên từ và mạch văn', 'GRAMMAR', 'Liên từ cho biết câu sau đi CÙNG hướng hay NGƯỢC hướng với câu trước — biết điều này là đoán được ý chính mà chưa cần hiểu hết từng chữ.

NGƯỢC HƯỚNG — ý quan trọng thường nằm SAU
しかし ／ ところが ／ でも
便利だ。しかし、使いすぎると 危ない。 → tác giả muốn nói về mặt nguy hiểm.

NGUYÊN NHÂN – KẾT QUẢ
そのため ／ だから ／ その結果

TÓM LẠI – DIỄN ĐẠT LẠI
つまり ／ 要するに → câu ngay sau thường chính là ý chính của cả đoạn.

THÊM Ý
それに ／ さらに ／ また

BÀI TẬP NHỎ
Mở bài "歩きスマホ" trong đề luyện đọc, khoanh tất cả liên từ, rồi thử đoán ý chính chỉ từ những câu đứng sau しかし và câu cuối bài.', 20, NULL, NULL, NOW() - INTERVAL 86400 MINUTE, NULL),
  (20015, 20003, 4, 'Chặng 4 · Kiểm tra đọc hiểu', 'READING', 'Làm đề "N3 · Luyện đọc hiểu — Bài nghị luận ngắn" và đạt từ 60% để hoàn thành lộ trình.

KHI LÀM
• Mỗi bài đọc có 2 câu hỏi, đoạn văn hiện một lần phía trên các câu.
• Áp dụng quy trình ba bước ở chặng 1.
• Làm xong, mở trang xem lại bài và đọc giải thích của từng câu sai — phần lớn lỗi ở N3 là chọn phương án "đúng một nửa".', 25, NULL, 20011, NOW() - INTERVAL 86400 MINUTE, 60),
  (20016, 20004, 1, 'Chặng 1 · Nhượng bộ: にもかかわらず・ものの', 'GRAMMAR', 'にもかかわらず — mặc dù (kết quả trái với dự đoán, văn viết)
雨にもかかわらず、多くの 人が 集まった。

ものの — tuy … nhưng (thừa nhận vế trước, vế sau không như mong đợi)
免許は 取った ものの、まだ 運転に 自信が ない。

PHÂN BIỆT
• にもかかわらず nhấn vào sự NGẠC NHIÊN trước kết quả.
• ものの nhấn vào vế sau CHƯA TỐT, thường mang sắc thái tiếc nuối.', 25, NULL, NULL, NOW() - INTERVAL 8640 MINUTE, NULL),
  (20017, 20004, 2, 'Chặng 2 · Phạm vi: を問わず・に限らず', 'GRAMMAR', 'を問わず — bất kể, không phân biệt (thường đi với cặp đối lập)
年齢を問わず、誰でも 参加できます。

に限らず — không chỉ … mà cả
この アニメは 子どもに限らず、大人にも 人気が ある。

MẸO
Thấy 男女, 昼夜, 経験の有無 đứng trước ô trống → gần như chắc chắn là を問わず.', 25, NULL, NULL, NOW() - INTERVAL 8640 MINUTE, NULL),
  (20018, 20004, 3, 'Chặng 3 · Kết quả: かいがあって・あげく', 'GRAMMAR', 'かいがあって — công sức không uổng, kết quả TỐT
練習した かいがあって、優勝できた。

あげく — sau một thời gian dài (thường vất vả), kết cục XẤU hoặc bất đắc dĩ
さんざん 迷った あげく、何も 買わなかった。

BẪY
Hai mẫu đều nói về "kết quả sau một quá trình". Nhìn kết quả tốt hay xấu để chọn.', 25, NULL, NULL, NOW() - INTERVAL 8640 MINUTE, NULL),
  (20019, 20005, 1, 'Bài 1 · Vì sao người Nhật dùng kính ngữ', 'GRAMMAR', 'Kính ngữ không chỉ để tỏ ra lễ phép. Nó cho người nghe biết mình đang đứng ở vị trí nào so với họ: người trong công ty ／ người ngoài, cấp trên ／ cấp dưới.

BA LOẠI
• 丁寧語: です ／ ます
• 尊敬語: nâng người khác
• 謙譲語: hạ mình', 20, NULL, NULL, NOW() - INTERVAL 17280 MINUTE, NULL),
  (20020, 20005, 2, 'Bài 2 · 尊敬語 thường gặp', 'GRAMMAR', 'いらっしゃる ／ 召し上がる ／ おっしゃる ／ ご覧になる
部長は 会議室に いらっしゃいます。', 20, NULL, NULL, NOW() - INTERVAL 17280 MINUTE, NULL),
  (20021, 20005, 3, 'Bài 3 · Kính ngữ với cấp trên', 'GRAMMAR', '社長が おっしゃいました。
お客様が いらっしゃいました。', 20, NULL, NULL, NOW() - INTERVAL 17280 MINUTE, NULL),
  (20022, 20006, 1, 'Chặng 1 · Nghe số và giờ', 'LISTENING', '(Đang soạn — chờ tải file nghe.)

MỤC TIÊU
Nghe và phân biệt 4時 (よじ) với 7時 (しちじ), 9時 (くじ) — ba giờ hay bị nghe nhầm nhất ở N5.', 15, NULL, NULL, NOW() - INTERVAL 2880 MINUTE, NULL);

